coverageStatusLabel function coverageStatusLabel(content, kind) {
    const { testable, linked } = statementCoverage(content);
    const status = expectedStatus(coverageTier(testable, linked));
    return status === null ? null : statusLabel(status, kind);
}
coverageTier function coverageTier(testable, linked) {
    if (testable === 0) {
        return "vacuous";
    }
    if (linked === 0) {
        return "none";
    }
    return linked < testable ? "partial" : "full";
}
expectedStatus function expectedStatus(tier) {
    return TIER_STATUS[tier];
}
statementCoverage function statementCoverage(content) {
    const statements = segmentStatements(content);
    const introOrdinals = buildIntroOrdinals(statements);
    const coverage = { testable: 0, linked: 0, unlinked: [] };
    for (const statement of statements) {
        if (classifyByHeuristic(statement, introOrdinals).testability !== "testable") {
            continue;
        }
        coverage.testable++;
        if (parseTestLinksInStatement(statement.text).length > 0) {
            coverage.linked++;
            continue;
        }
        // `Statement.line` is optional (test doubles omit it), so fall back to line 1.
        coverage.unlinked.push({ text: statement.text, line: statement.line ?? 1 });
    }
    return coverage;
}
statusLabel function statusLabel(status, kind) {
    const label = STATUS_LABEL[kind][status];
    enforceTrue(label !== undefined, Error, `no ${kind} label for status "${status}"`);
    return label;
}
unlinkedTestableStatements function unlinkedTestableStatements(content) {
    return statementCoverage(content).unlinked;
}

